/**
 * CSRF guard for mutating serve HTTP requests.
 *
 * Default serve trusts loopback (`localDevStrict`). CLI, webhooks, and the
 * control plane send no `Origin`. A page in the developer's browser is also
 * loopback, and a CORS-simple POST (e.g. text/plain) skips preflight, so any
 * site they visit can drive sessions, tools, and channel routes.
 *
 * `Origin` is the primary signal (forbidden header; `Origin: null` never
 * matches). No browser signals means a non-browser client. `Sec-Fetch-Site`
 * is the fallback when Origin is omitted.
 */
const SAFE_METHODS = new Set(["GET", "HEAD", "OPTIONS"]);
export function browserOriginGuardOptionsForPublicUrl(publicUrl) {
    if (publicUrl === undefined) {
        return undefined;
    }
    try {
        return { allowedOriginHosts: new Set([new URL(publicUrl).host]) };
    }
    catch {
        return undefined;
    }
}
export function isTrustedBrowserMutation(request, options) {
    if (SAFE_METHODS.has(request.method.toUpperCase())) {
        return true;
    }
    const origin = request.headers.get("origin");
    if (origin !== null) {
        return originHostMatches(origin, request.url, options?.allowedOriginHosts);
    }
    // Some Safari versions omit Origin on same-origin POST but still send Fetch Metadata.
    const secFetchSite = request.headers.get("sec-fetch-site");
    if (secFetchSite !== null) {
        return secFetchSite === "same-origin" || secFetchSite === "none";
    }
    return true;
}
function originHostMatches(origin, requestUrl, extraAllowedHosts) {
    let originUrl;
    let selfUrl;
    try {
        originUrl = new URL(origin);
        selfUrl = new URL(requestUrl);
    }
    catch {
        return false;
    }
    return originUrl.host === selfUrl.host || extraAllowedHosts?.has(originUrl.host) === true;
}
